<?php namespace App\Http\Middleware; use Closure; use Illuminate\Http\Request; class SetLocale { public function handle(Request $request, Closure $next) { if (session()->has('locale')) { app()->setLocale(session('locale')); } elseif (auth()->check() && auth()->user()->langue) { app()->setLocale(auth()->user()->langue); } return $next($request); } }